-- Run this once in the Supabase dashboard: SQL Editor -> New query -> Run
-- Matches server/db.js: ids are generated by the database, user name column is "username".

create table if not exists public.users (
  id            uuid primary key default gen_random_uuid(),
  username      text not null,
  email         text not null unique,
  role          text,
  avatar        text,
  password_hash text not null,
  created_at    timestamptz not null default now()
);

create table if not exists public.blogs (
  id            uuid primary key default gen_random_uuid(),
  title         text not null,
  slug          text,
  excerpt       text,
  content       text not null,
  category      text,
  cover_image   text,
  tags          jsonb not null default '[]'::jsonb,
  reading_time  integer not null default 1,
  author_id     uuid not null references public.users(id) on delete cascade,
  author_name   text,
  author_role   text,
  author_avatar text,
  likes         integer not null default 0,
  claps         integer not null default 0,
  created_at    timestamptz not null default now()
);

create index if not exists blogs_created_at_idx on public.blogs (created_at desc);

-- The backend uses the service_role key, which bypasses RLS.
-- RLS with no policies blocks direct access with the public key,
-- so password hashes can never be read from the browser.
alter table public.users enable row level security;
alter table public.blogs enable row level security;
